def normalize_house_pdf_text(value):
    output = []

    for char in str(value or ""):
        code = ord(char)

        if HOUSE_BROKEN_UNICODE_START <= code <= HOUSE_BROKEN_UNICODE_END:
            output.append(chr(code - HOUSE_BROKEN_UNICODE_OFFSET))
        else:
            output.append(char)

    return "".join(output)

